css:
/* 2円を噛み合わせる */
.photo{position:relative; z-index:2; width:100px; aspect-ratio:1;
  border-radius:50%; border:4px solid #12569e; overflow:hidden}
.clock{position:absolute; z-index:1; left:-58px; bottom:6px;
  width:82px; aspect-ratio:1; border-radius:50%; border:4px solid #12569e;
  background:conic-gradient(#f5b731 0 25%,#fff 0)}

/* 中心の円を"まとめ"にする */
.hub{position:absolute; left:50%; top:50%; translate:-50% -50%; z-index:2;
  width:150px; aspect-ratio:1; border-radius:50%; background:#f5d928;
  display:grid; place-items:center; text-align:center; padding:16px}

/* リングに埋め込んで欠けさせる（欠けを中心方向に揃える） */
.ring{position:relative; width:230px; aspect-ratio:1; border-radius:50%; background:#fff}
.dot{position:absolute; z-index:1; width:76px; aspect-ratio:1;
  border-radius:50%; background:#7b2230}
.hole{position:absolute; z-index:2; inset:38px; border-radius:50%; background:#fff}
